I'll take a robust approach: generate docstrings programmatically from each module's top-level definitions, then insert them. First, let me build and run the full script in one go.

```json
{"tool": "run_bash", "args": {"cmd": "cd /tmp/agentrun/django_2 && cat > /tmp/gen_apply.py <<'PYEOF'
import ast, os

ROOTS = ['django/db', 'django/utils', 'django/core']

def has_doc(tree):
    b = tree.body
    return bool(b) and isinstance(b[0], ast.Expr) and isinstance(b[0].value, ast.Constant) and isinstance(b[0].value.value, str)

def describe(path, tree):
    base = os.path.basename(path)
    pkg = os.path.dirname(path).replace('/', '.')
    classes = [n.name for n in tree.body if isinstance(n, ast.ClassDef)]
    funcs = [n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
    if base == '__init__.py':
        return 'Package initializer for the %s package.' % pkg
    parts = []
    if classes:
        parts.append('Defines ' + ', '.join(classes[:4]) + ('.' if len(classes) <= 4 else ', among others.'))
    if funcs:
        parts.append('Provides ' + ', '.join(funcs[:4]) + ('.' if len(funcs) <= 4 else ', among other helpers.'))
    if not parts:
        parts.append('Module %s.' % base[:-3])
    return ' '.join(parts)

def insert(path, doc):
    with open(path, encoding='utf-8') as f:
        lines = f.readlines()
    # find insertion point: after shebang and encoding comment lines
    idx = 0
    if lines and lines[0].startswith('#!'):
        idx = 1
    # skip encoding comment (PEP 263) on line 1 or 2
    j = idx
    while j < len(lines) and j < idx + 1 and lines[j].startswith('#') and 'coding' in lines[j]:
        j += 1
    idx = j
    # skip blank lines right after header? keep them; insert before first non-header content
    # Actually insert docstring right at idx, followed by a blank line if next line isn't blank
    block = ['"""%s"""\n' % doc]
    if idx < len(lines) and lines[idx].strip() != '':
        block.append('\n')
    new = lines[:idx] + block + lines[idx:]
    with open(path, 'w', encoding='utf-8') as f:
        f.writelines(new)

changed = 0
for root in ROOTS:
    for dp, _, fs in os.walk(root):
        for fn in sorted(fs):
            if not fn.endswith('.py'):
                continue
            p = os.path.join(dp, fn)
            with open(p, encoding='utf-8') as f:
                src = f.read()
            try:
                tree = ast.parse(src)
            except SyntaxError:
                continue
            if has_doc(tree):
                continue
            doc = describe(p, tree)
            insert(p, doc)
            changed += 1
print('changed', changed)
PYEOF
python3 /tmp/gen_apply.py"}}
